# Requires Windows PowerShell 5.1 (64 bit), .NET Framework 4.x, running Solid Edge.
param([string]$OutputFolder = '')
$ErrorActionPreference = 'Stop'
# ---- privacy functions (begin) ----
# Solid Edge stores the absolute path of every linked file inside assemblies, drawings and linked parts, STEP headers name the
# file they were written to, and Solid Edge's STEP translation logs quote full paths (measured on Solid Edge 2026, 2026-11-25).
# So the builder always builds in a neutral folder under C:\Users\Public, and nothing that names the person running it may
# reach the zip or the console: a user folder (C:\Users\<name>, a share's \Users\<name>, a relocated profile, OneDrive or
# Documents folder), the Windows user name or the computer name inside a path.
$script:PrivacyDropped = @{}
$script:PrivacyNotes = New-Object System.Collections.Generic.List[string]
function Get-PublicRoot {
    $public = [string]$env:PUBLIC
    if (-not $public) { $public = 'C:\Users\Public' }
    return (Join-Path $public 'FixtureOut')
}
function Get-PrivateName {
    # The user name, when it is long and unusual enough to search for (not 'admin', 'user', 'owner' and the like).
    $n = [string]$env:USERNAME
    $common = @('user', 'users', 'admin', 'administrator', 'owner', 'guest', 'test', 'public', 'default', 'home', 'work', 'pc', 'desktop', 'windows', 'cad', 'design')
    if ($n.Length -ge 3 -and $common -notcontains $n.ToLowerInvariant()) { return $n }
    return ''
}
function Get-PrivateWords {
    # Words that name the person or the computer, searched for inside paths (and as whole words in logs and on the console):
    # the user name, the profile folder's own name (often not the user name: 'jsmith.ACME'), the computer name, the domain
    # and the logon server. Short or common words ('admin', 'WORKGROUP' and the like) are left alone.
    $common = @('user', 'users', 'admin', 'administrator', 'owner', 'guest', 'test', 'public', 'default', 'home', 'work', 'pc', 'desktop', 'windows', 'cad', 'design', 'workgroup', 'domain', 'localhost')
    $words = @((Get-PrivateName), (Split-Path -Leaf ([Environment]::GetFolderPath('UserProfile'))), [string]$env:COMPUTERNAME, [string]$env:USERDOMAIN, ([string]$env:LOGONSERVER).TrimStart('\'))
    return @($words | Where-Object { $_ -and $_.Length -ge 3 -and $common -notcontains $_.ToLowerInvariant() } | Select-Object -Unique)
}
$script:UncPrefix = '(?<=^|[\s"''(=,;])\\\\[^\\/\s"''<>|]+\\[^\\/\s"''<>|]+'
$script:UncPrefixJson = '(?<=")\\\\\\\\[^\\/\s"''<>|]+\\\\[^\\/\s"''<>|]+'
function Get-PrivatePattern {
    # The same text as PrivatePatternText() in the VB module (the self-test compares them).
    $sep = '[\\/]{1,4}'
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add('(?:[a-z]:)?' + $sep + 'users' + $sep + '(?!(?:public|default|all users|shared)(?=[\\/\s"''<>|;,\x00]|$))[^\\/:*?"<>|\r\n\x00]{1,80}')
    $homes = @([Environment]::GetFolderPath('UserProfile'), [Environment]::GetFolderPath('MyDocuments'), [Environment]::GetFolderPath('Desktop'), $env:OneDrive, $env:OneDriveCommercial, $env:OneDriveConsumer)
    foreach ($folder in $homes) {
        if (-not $folder) { continue }
        $folder = ([string]$folder).TrimEnd('\')
        if ($folder.Length -le 3 -or $folder -match ('(?i)^[a-z]:' + $sep + 'users' + $sep)) { continue }
        foreach ($form in @($folder, $folder.Replace('\', '\\'), $folder.Replace('\', '/'))) {
            $escaped = [Regex]::Escape($form)
            if (-not $parts.Contains($escaped)) { $parts.Add($escaped) }
        }
    }
    return '(?i)(?:' + ($parts -join '|') + ')'
}
$script:PathToken = '(?i)(?:[a-z]:)?(?:[\\/]{1,4}[^\\/:*?"<>|\r\n\x00]+)+'
$script:PathTail = '[^\\/:*?"<>|\r\n\x00]*(?:[\\/]{1,4}[^\\/:*?"<>|\r\n\x00]*)*'
$script:JsonValue = '"(?:[^"\\]|\\.)*"(?!\s*:)'
function Get-NamePattern {
    # The private words as whole words: not next to a letter or digit (start of file, a tab, '["', a binary length byte).
    $words = @(Get-PrivateWords)
    if (-not $words.Count) { return '' }
    return '(?i)(?<![a-z0-9])(?:' + ((@($words | ForEach-Object { [Regex]::Escape($_) })) -join '|') + ')(?![a-z0-9])'
}
function Hide-PrivatePath([string]$text, [switch]$Json) {
    # A user folder becomes %USERPROFILE% and a \\server\share \\<server>\<share>, each with the rest of its path up to the end
    # of the line, a quote or <>| ('...\Dropbox (Acme Corp). next', '...\My Part.x'). The private words become <private>
    # inside any other path, and in JSON string values (never keys); outside JSON, everywhere.
    $text = [Regex]::Replace($text, (Get-PrivatePattern) + $script:PathTail, '%USERPROFILE%')
    $text = [Regex]::Replace($text, $script:UncPrefix + $script:PathTail, '\\<server>\<share>')
    $text = [Regex]::Replace($text, $script:UncPrefixJson + $script:PathTail, '\\\\<server>\\<share>')
    $names = Get-NamePattern
    if ($names) {
        $text = [Regex]::Replace($text, $script:PathToken, { param($m) [Regex]::Replace($m.Value, $names, '<private>') })
        if ($Json) { $text = [Regex]::Replace($text, $script:JsonValue, { param($m) [Regex]::Replace($m.Value, $names, '<private>') }) }
        else { $text = [Regex]::Replace($text, $names, '<private>') }
    }
    return $text
}
function Test-PrivateText([string]$text, [switch]$Json) {
    # What is still private in scrubbed text ('' when nothing).
    if ($text -match (Get-PrivatePattern)) { return 'a user folder path' }
    foreach ($m in [Regex]::Matches($text, $script:UncPrefix)) { if ($m.Value -notmatch '^\\\\<server>\\<share>$') { return 'a share path' } }
    $names = Get-NamePattern
    if ($names) {
        foreach ($m in [Regex]::Matches($text, $script:PathToken)) { if ($m.Value -match $names) { return 'a user, computer or domain name in a path' } }
        if ($Json) { foreach ($m in [Regex]::Matches($text, $script:JsonValue)) { if ($m.Value -match $names) { return 'a user, computer or domain name in a value' } } }
        elseif ($text -match $names) { return 'a user, computer or domain name' }
    }
    return ''
}
function Test-BuildFolder([string]$folder) {
    # '' when the builder may build straight in this folder: under C:\Users\Public, naming no one.
    $public = [IO.Path]::GetFullPath((Split-Path -Parent (Get-PublicRoot))).TrimEnd('\') + '\'
    if (-not ($folder.TrimEnd('\') + '\').StartsWith($public, [StringComparison]::OrdinalIgnoreCase)) { return 'it is not under ' + $public.TrimEnd('\') }
    if ($folder -match (Get-PrivatePattern)) { return 'it is inside a user folder' }
    foreach ($n in Get-PrivateWords) {
        if (@($folder.Split([char[]]'\/') | Where-Object { $_.IndexOf($n, [StringComparison]::OrdinalIgnoreCase) -ge 0 }).Count) { return 'a folder in its path contains your user, computer or domain name' }
    }
    return ''
}
function Remove-PrivateFile([string]$path) {
    # Fail closed: delete (three tries), else empty the file. Either way it is left out of the zip.
    $when = [DateTime]::MinValue
    try { $when = [IO.File]::GetLastWriteTimeUtc($path) } catch { }
    $script:PrivacyDropped[$path] = $when
    for ($i = 0; $i -lt 3; $i++) {
        try { [IO.File]::Delete($path) } catch { }
        if (-not [IO.File]::Exists($path)) { return }
        Start-Sleep -Milliseconds 300
    }
    try { [IO.File]::WriteAllBytes($path, [byte[]]@()) } catch { }
}
function Test-PrivateBytes([byte[]]$bytes, [string]$names = '') {
    # The VB scan: plain text in five readings, and every zlib, gzip and zip-deflate stream inflated; with $names, the private
    # words too. A limit reached is a hit.
    if (-not ('SolidEdgeFixtureBuilder' -as [type])) { throw 'the privacy scan is not loaded' }
    return [string][SolidEdgeFixtureBuilder]::PrivateInBytes($bytes, $names)
}
function Update-StepHeader([string]$path) {
    # FILE_NAME keeps the bare file name; author, organization and authorization are emptied. A header that cannot be
    # rewritten throws (the file is then removed).
    $latin = [Text.Encoding]::GetEncoding(28591)
    $text = $latin.GetString([IO.File]::ReadAllBytes($path))
    if ($text -notmatch 'FILE_NAME') { return }
    # Solid Edge writes a /* comment */ before each field (measured on Solid Edge 2026, 2026-11-25), so blanks may be comments.
    $s = "'(?:[^']|'')*'"
    $ws = '(?:\s|/\*[\s\S]*?\*/)*'
    $list = '\(' + $ws + '(?:' + $s + $ws + ',?' + $ws + ')*\)'
    $rx = 'FILE_NAME' + $ws + '\(' + $ws + $s + $ws + ',' + $ws + '(' + $s + ')' + $ws + ',' + $ws + $list + $ws + ',' + $ws + $list + $ws + ',' + $ws + '(' + $s + ')' + $ws + ',' + $ws + '(' + $s + ')' + $ws + ',' + $ws + $s + $ws + '\)'
    $bare = [IO.Path]::GetFileName($path).Replace("'", "''")
    $m = [Regex]::Match($text, $rx)
    if (-not $m.Success) { throw 'its STEP header could not be rewritten' }
    $header = "FILE_NAME('" + $bare + "'," + $m.Groups[1].Value + ",(''),(''),"  + $m.Groups[2].Value + ',' + $m.Groups[3].Value + ",'')"
    $text = $text.Substring(0, $m.Index) + $header + $text.Substring($m.Index + $m.Length)
    [IO.File]::WriteAllBytes($path, $latin.GetBytes($text))
}
function Invoke-PrivacySweep([string]$run) {
    # Every file in the run folder, listed by a recipe or not. STEP headers are rewritten. Text (.log, .json, .txt) is scrubbed
    # in its own encoding and checked again; every file is byte-scanned. A file that still holds something private, or that
    # cannot be read, rewritten or scanned, is removed.
    $latin = [Text.Encoding]::GetEncoding(28591)
    foreach ($t in @(Get-ChildItem -LiteralPath $run -Recurse -File -Force)) {
        $rel = $t.FullName.Substring($run.TrimEnd('\').Length + 1)
        try {
            if ($t.Extension -in '.step', '.stp') { Update-StepHeader $t.FullName }
            $bytes = [IO.File]::ReadAllBytes($t.FullName)
            if ($t.Extension -in '.log', '.json', '.txt', '.dxf') {
                $json = $t.Extension -eq '.json'
                if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) { $enc = [Text.Encoding]::Unicode; $skip = 2 }
                elseif ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { $enc = [Text.Encoding]::UTF8; $skip = 3 }
                else { $enc = $latin; $skip = 0 }
                $text = $enc.GetString($bytes, $skip, $bytes.Length - $skip)
                $clean = Hide-PrivatePath $text -Json:$json
                if ($clean -ne $text) {
                    $out = $enc.GetBytes($clean)
                    if ($skip -gt 0) { $out = [byte[]]($enc.GetPreamble() + $out) }
                    [IO.File]::WriteAllBytes($t.FullName, [byte[]]$out)
                    $bytes = [IO.File]::ReadAllBytes($t.FullName)
                }
                $left = Test-PrivateText ($enc.GetString($bytes, $skip, $bytes.Length - $skip)) -Json:$json
                if ($left) { throw ('it still holds ' + $left) }
            }
            # Native Solid Edge documents always carry the Windows user and computer names in their own streams (Last Author,
            # version history, the Parasolid header); the builder cannot remove those, central redaction does before anything is
            # published. They are scanned for user folders. Every other file, of any extension, is scanned for the names too.
            if ($t.Extension -in '.par', '.psm', '.asm', '.dft', '.pwd') { $hit = Test-PrivateBytes $bytes }
            else { $hit = Test-PrivateBytes $bytes (Get-NamePattern) }
            if ($hit) { throw ('it holds ' + $hit) }
        } catch {
            Remove-PrivateFile $t.FullName
            $script:PrivacyNotes.Add('privacy: removed ' + (Hide-PrivatePath $rel) + ': ' + (Hide-PrivatePath $_.Exception.Message))
        }
    }
}
function Update-PrivacyResults([string]$run) {
    # A recipe whose file the sweep removed fails in results.json: by its file list, or, for a file no recipe lists, by the
    # recipe that was running when the file was written. Nothing claims a file the zip does not hold.
    if ($script:PrivacyDropped.Count -eq 0) { return }
    $path = Join-Path $run 'results.json'
    if (-not [IO.File]::Exists($path) -or $script:PrivacyDropped.ContainsKey($path)) { return }
    $serializer = New-Object System.Web.Script.Serialization.JavaScriptSerializer
    $serializer.MaxJsonLength = [int]::MaxValue
    $rows = $serializer.DeserializeObject([IO.File]::ReadAllText($path))
    $owned = @{}
    foreach ($row in $rows) {
        $lost = @(@($row['files']) | Where-Object { $script:PrivacyDropped.ContainsKey((Join-Path $run ([string]$_))) })
        foreach ($f in $lost) { $owned[(Join-Path $run ([string]$f))] = $true }
        $started = [DateTime]::MinValue
        if ($row.ContainsKey('started_utc')) { $started = [DateTime]::Parse([string]$row['started_utc'], $null, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() }
        $ended = $started.AddSeconds([double]$row['seconds'] + 2)
        foreach ($dropped in @($script:PrivacyDropped.Keys)) {
            $when = $script:PrivacyDropped[$dropped]
            $rel = $dropped.Substring($run.TrimEnd('\').Length + 1)
            if ($started -ne [DateTime]::MinValue -and $when -ge $started.AddSeconds(-2) -and $when -le $ended -and $lost -notcontains $rel) {
                $lost += $rel; $owned[$dropped] = $true
            }
        }
        if ($lost.Count) {
            $row['status'] = 'failed'
            $row['error'] = [string]$row['id'] + ': privacy: ' + ((@($lost) | ForEach-Object { Hide-PrivatePath ([string]$_) }) -join ', ') + ' removed before zipping: it held something private or could not be checked'
            $row['files'] = [object[]]@()
        }
    }
    [IO.File]::WriteAllText($path, $serializer.Serialize($rows))
    foreach ($dropped in @($script:PrivacyDropped.Keys)) {
        if (-not $owned.ContainsKey($dropped) -and $dropped -ne $path) { $script:PrivacyNotes.Add('privacy: ' + (Hide-PrivatePath $dropped.Substring($run.TrimEnd('\').Length + 1)) + ' belonged to no recipe') }
    }
}
# ---- privacy functions (end) ----
try {
    if ($PSVersionTable.PSEdition -eq 'Core') { throw 'Use Windows PowerShell 5.1, not PowerShell Core.' }
    if ([Threading.Thread]::CurrentThread.ApartmentState -ne 'STA') { throw 'Start powershell.exe -STA.' }
    # Build straight in the chosen folder only when it is under C:\Users\Public and names no one; otherwise build in
    # C:\Users\Public\FixtureOut and copy the finished zip to the chosen folder. The files then record only that neutral folder.
    $publicRoot = Get-PublicRoot
    $chosen = if ($OutputFolder) { [IO.Path]::GetFullPath($OutputFolder) } else { $publicRoot }
    $buildParent = if (Test-BuildFolder $chosen) { $publicRoot } else { $chosen }
    $source = @'
Option Explicit On
Option Strict Off
Imports System
Imports System.IO
Imports Microsoft.VisualBasic
Imports System.Collections.Generic
Imports System.Web.Script.Serialization

Public Module SolidEdgeFixtureBuilder
    Public Const BuilderVersion As String = "2026.11.27.2"
    Public RunFolder As String
    Private currentRecipe As String
    Private currentStep As String
    Private Property stepName As String
        Get
16: Return currentStep
        End Get
        Set(ByVal value As String)
            currentStep=value
20: If RunFolder IsNot Nothing AndAlso Directory.Exists(RunFolder) Then
21: Dim serializer As New JavaScriptSerializer()
                File.WriteAllText(Path.Combine(RunFolder,"progress.log"),serializer.Serialize(New Dictionary(Of String,Object) From {{"id",currentRecipe},{"step",value}}))
            End If
        End Set
    End Property
    <System.Runtime.InteropServices.DllImport("oleaut32.dll", CharSet:=System.Runtime.InteropServices.CharSet.Unicode, PreserveSig:=False)>
    Private Sub LoadTypeLibEx(ByVal filename As String, ByVal kind As Integer, ByRef library As System.Runtime.InteropServices.ComTypes.ITypeLib)
    End Sub
    Private programFolder As String
    Private apiTypes As New Dictionary(Of String, Type)()
    Private Sub ImportLibrary(ByVal filename As String)
        Try
33: Dim library As System.Runtime.InteropServices.ComTypes.ITypeLib = Nothing
34: LoadTypeLibEx(filename, 2, library)
35: Dim assembly As System.Reflection.Assembly = InteropSink.ConvertLibrary(library)
        For Each loaded As System.Reflection.Assembly In InteropSink.Cache.Values
            For Each item As Type In loaded.GetTypes()
38: If Not apiTypes.ContainsKey(item.Name) Then apiTypes.Add(item.Name, item)
            Next
        Next
        Catch ex As Exception
42: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Sub
    Private Sub InitializeInterop(ByVal app As Object)
        Try
48: If programFolder IsNot Nothing Then Return
49: Dim processId As Integer = CInt(app.ProcessID)
50: If processId = 0 Then Throw New Exception("Cannot find running Solid Edge process")
51: Dim folder As String = Path.GetDirectoryName(System.Diagnostics.Process.GetProcessById(processId).MainModule.FileName)
52: ImportLibrary(Path.Combine(folder, "Part.tlb"))
53: ImportLibrary(Path.Combine(folder, "constant.tlb"))
        programFolder = folder
        Catch ex As Exception
56: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Sub
    Private Function ApiType(ByVal name As String) As Type
        Try
62: If apiTypes.ContainsKey(name) Then Return apiTypes(name)
        ' Additional Solid Edge libraries are discovered under this running install.
        For Each filename As String In Directory.GetFiles(programFolder, "*.tlb")
65: ImportLibrary(filename)
66: If apiTypes.ContainsKey(name) Then Return apiTypes(name)
        Next
68: Throw New Exception("Installed type libraries have no type " & name)
        Catch ex As Exception
70: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function ApiConstant(ByVal group As String, ByVal name As String) As Object
        Try
76: Return [Enum].Parse(ApiType(group), name, False)
        Catch ex As Exception
78: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function TypedArray(ByVal name As String, ByVal items As Object()) As Array
        Try
84: Dim element As Type
        Select Case name
            Case "Double" : element = GetType(Double)
            Case "Int32" : element = GetType(Integer)
            Case "Object" : element = GetType(Object)
            Case Else : element = ApiType(name)
        End Select
91: If element IsNot GetType(Object) AndAlso Not element.IsInterface AndAlso Not element.IsPrimitive AndAlso Not element.IsEnum Then Throw New Exception("Expected an interface, numeric or Object array: " & name)
92: Dim result As Array = Array.CreateInstance(element, items.Length)
        For i As Integer = 0 To items.Length - 1
94: result.SetValue(If(element Is GetType(Integer), CType(Convert.ToInt32(items(i)), Object), If(element.IsEnum, [Enum].ToObject(element, Convert.ToInt32(items(i))), items(i))), i)
        Next
96: Return result
        Catch ex As Exception
98: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Sub LogMessage(ByVal message As String)
        Console.WriteLine(message)
        File.AppendAllText(Path.Combine(RunFolder, "FixtureBuilder.log"), message & Environment.NewLine)
    End Sub
    Private Function DispatchError(ByVal ex As Exception) As Boolean
        While ex.InnerException IsNot Nothing
            ex = ex.InnerException
        End While
110: Return ex.HResult = -2147352571 OrElse ex.HResult = -2147024809
    End Function
    Private Sub LogDispatchFailure(ByVal ex As Exception, ByVal operation As String)
113: If Not DispatchError(ex) Then Return
        Try
115: Dim parts As String() = operation.Split("."c)
116: Dim owner As Type = ApiType(parts(parts.Length - 2))
            For Each method As System.Reflection.MethodInfo In owner.GetMethods()
118: If method.Name <> parts(parts.Length - 1) Then Continue For
119: Dim parameters As New List(Of String)()
                For Each parameter As System.Reflection.ParameterInfo In method.GetParameters()
                    parameters.Add(parameter.Name & ":" & parameter.ParameterType.ToString() & If(parameter.IsOptional, " optional", ""))
                Next
                LogMessage(operation & " installed signature: (" & String.Join(", ", parameters.ToArray()) & ")")
            Next
        Catch diagnostic As Exception
            LogMessage(operation & " signature diagnostic failed: " & SafeError(diagnostic))
        End Try
    End Sub
    Private Function ArrayShape(ByVal source As Array, ByVal kind As Integer, ByVal values As Boolean) As Array
130: Dim items(source.Length - 1) As Object
        source.CopyTo(items, 0)
132: If values AndAlso kind = 2 Then
            For i As Integer = 0 To items.Length - 1
                items(i) = [Enum].ToObject(ApiType("FeaturePropertyConstants"), Convert.ToInt32(items(i)))
