        End If
137: Return TypedArray(If(values, If(kind = 0, "Int32", If(kind = 1, "Object", "FeaturePropertyConstants")), If(kind = 0, "Profile", "Object")), items)
    End Function
    Private Function ExtrudeTwoSided(ByVal doc As Object, ByVal profile As Object, ByVal up As Double, ByVal down As Double) As Object
        Try
