189: Dim method As System.Reflection.MethodInfo = ApiType("Splits").GetMethod("Add")
190: Dim values As Object() = New Object() {1, TypedArray("Object", New Object() {model.Body}), 1, TypedArray("Object", New Object() {tool}), 0, 0}
191: Dim before As Integer = CInt(doc.Models.Count)
