    End Function
    Private Function FromToFace(ByVal model As Object, ByVal kind As String, ByVal profile As Object, ByVal fromPlane As Object, ByVal face As Object, ByVal side As Integer) As Object
        Try
202: Dim features As Object = CallByName(model, kind, CallType.Get)
        Try
204: Return features.AddFromTo(profile, 1, fromPlane, face)
        Catch ex As System.Runtime.InteropServices.COMException
            ' Measured on our Solid Edge test PC: the from-to call reports E_FAIL when the end face is the curved face of an arc profile.
            ' A finite extrusion that ends inside the body gives the same solid: it runs from the profile plane to the
            ' middle of the end face's range, which lies inside the material.
            LogMessage("AddFromTo to a curved face failed (" & SafeError(ex) & "); using a finite extrusion to the middle of the face")
210: Dim root(2), normal(2), low(2), high(2) As Double
            fromPlane.GetRootPoint(root)
            fromPlane.GetNormal(normal)
213: face.GetRange(low, high)
214: Dim depth As Double = 0
            For k As Integer = 0 To 2
                depth += ((low(k) + high(k)) / 2 - root(k)) * normal(k)
            Next
218: Return features.AddFinite(profile, 1, side, Math.Abs(depth))
        End Try
        Catch ex As Exception
221: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
