        method.Invoke(model.SplitFaces, BindFlangeArguments(method, New Object() {1, TypedArray("Object", New Object() {face}), 1, TypedArray("Object", New Object() {tool})}))
239: Dim after As Integer = CInt(model.Body.Faces(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll")).Count)
