    Private Sub CheckHolePattern(ByVal model As Object, ByVal diameter As Double, ByVal minX As Double, ByVal maxX As Double, ByVal minY As Double, ByVal maxY As Double)
        Try
        ' The hole circles are the edges as wide as the hole in both directions and flat in z.
249: Dim edges As Object = model.Body.Edges(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
250: Dim found As Integer = 0
251: Dim lowX As Double = Double.PositiveInfinity, highX As Double = Double.NegativeInfinity, lowY As Double = Double.PositiveInfinity, highY As Double = Double.NegativeInfinity
        For i As Integer = 1 To CInt(edges.Count)
253: Dim lo(2), hi(2) As Double
            edges.Item(i).GetRange(lo, hi)
255: If Math.Abs(hi(2) - lo(2)) < 0.0000001 AndAlso Math.Abs((hi(0) - lo(0)) - diameter) < 0.000001 AndAlso Math.Abs((hi(1) - lo(1)) - diameter) < 0.000001 Then
                found += 1
257: Dim cx As Double = (lo(0) + hi(0)) / 2, cy As Double = (lo(1) + hi(1)) / 2
                lowX = Math.Min(lowX, cx) : highX = Math.Max(highX, cx) : lowY = Math.Min(lowY, cy) : highY = Math.Max(highY, cy)
            End If
        Next
261: If found = 0 Then Throw New Exception("pattern: no hole circles found")
262: If Math.Abs(lowX - minX) > 0.000001 OrElse Math.Abs(highX - maxX) > 0.000001 OrElse Math.Abs(lowY - minY) > 0.000001 OrElse Math.Abs(highY - maxY) > 0.000001 Then
263: Dim ex As New Exception("pattern holes span x " & CStr(Math.Round(lowX * 1000, 3)) & " to " & CStr(Math.Round(highX * 1000, 3)) & ", y " & CStr(Math.Round(lowY * 1000, 3)) & " to " & CStr(Math.Round(highY * 1000, 3)) & " mm; expected x " & CStr(Math.Round(minX * 1000, 3)) & " to " & CStr(Math.Round(maxX * 1000, 3)) & ", y " & CStr(Math.Round(minY * 1000, 3)) & " to " & CStr(Math.Round(maxY * 1000, 3)))
            ex.Data("ExpectationMismatch") = True
            Throw ex
        End If
        Catch ex As Exception
268: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Sub
