    Private Function ExactVolume(ByVal body As Object) As Double
        ' Body.Volume runs at a reduced default accuracy: on oblique curved geometry it is off by up to 0.2 percent
        ' (a 3D sweep read 300.25 against an exact 299.43). Full requested accuracy converges to the exact volume.
        Try
285: Dim volume, area, mass, achieved As Double, status As Integer
286: Dim cog(2), cov(2), moments(5), principal(2), axes(8), radii(2) As Double
            body.ComputePhysicalProperties(1.0, 1.0, volume, area, mass, cog, cov, moments, principal, axes, radii, achieved, status)
288: If status = 1 AndAlso volume > 0 AndAlso Not Double.IsNaN(volume) AndAlso Not Double.IsInfinity(volume) Then Return volume
            LogMessage("Exact volume status=" & CStr(status) & "; using Body.Volume")
        Catch ex As Exception
            LogMessage("Exact volume unavailable: " & SafeError(ex) & "; using Body.Volume")
        End Try
293: Return CDbl(body.Volume)
    End Function
    Private Function Path3D(ByVal doc As Object, ByVal points As Array) As Object
        Try
        ' One connected 3D polyline as locked lines; the sweep follows the composite curve derived from its edges.
298: Dim count As Integer = points.Length \ 3 - 1
299: If count < 1 Then Throw New Exception("A 3D path needs at least two points")
300: Dim sketch As Object = doc.Sketches3D.Add()
        sketch.Active = True
302: Dim lines(count - 1) As Object
        For i As Integer = 0 To count - 1
            lines(i) = sketch.Lines3D.Add(CDbl(points.GetValue(3 * i)), CDbl(points.GetValue(3 * i + 1)), CDbl(points.GetValue(3 * i + 2)), CDbl(points.GetValue(3 * i + 3)), CDbl(points.GetValue(3 * i + 4)), CDbl(points.GetValue(3 * i + 5)))
        Next
        For i As Integer = 0 To count - 1
            sketch.Sketch3DRelations.AddLock(lines(i))
        Next
        sketch.Active = False
310: Dim found As Object = sketch.Sketch3DFeature.Edges(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
311: If CInt(found.Count) <> count Then Throw New Exception("3D path has " & CStr(found.Count) & " edges; expected " & CStr(count))
312: Dim items(count - 1) As Object
        For i As Integer = 0 To count - 1
            items(i) = found.Item(i + 1)
        Next
316: Dim derived As Object = doc.Constructions.DerivedCurves.Add(count, TypedArray("Edge", items), ApiConstant("DerivedCurveTypeConstants", "igDCComposite"))
317: Return derived.Edges(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
        Catch ex As Exception
319: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function Sweep3D(ByVal doc As Object, ByVal path As Object, ByVal section As Object) As Object
        Try
        ' Edge-based trace curve (49), one profile-based cross section (48), material side igLeft, no start/end extents.
326: Dim args As Object() = {1, TypedArray("Object", New Object() {path}), TypedArray("Int32", New Object() {ApiConstant("FeaturePropertyConstants", "igEdgeBasedCrossSection")}), 1, TypedArray("Profile", New Object() {section}), TypedArray("Int32", New Object() {ApiConstant("FeaturePropertyConstants", "igProfileBasedCrossSection")}), TypedArray("Object", New Object() {New Double() {0, 0}}), Nothing, ApiConstant("FeaturePropertyConstants", "igLeft"), ApiConstant("FeaturePropertyConstants", "igNone"), 0.0, Nothing, ApiConstant("FeaturePropertyConstants", "igNone"), 0.0, Nothing}
327: Return InvokeModels(doc.Models, "AddSweptProtrusion", args)
        Catch ex As Exception
329: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    ' The flat spiral coil (measured on our Solid Edge test PC, 2026-11-24, Solid Edge 2026). Constructions.HelicalCurves.AddSpiralCurve builds
    ' only with the axis given as an edge of a design body or of the base coordinate system (a profile's axis of revolution,
    ' a 2D or 3D sketch line and a construction-surface edge all leave the curve failed), and only with a base plane that
    ' contains the axis (the plane square to it fails). The start is a space point at the circle center. With the Y axis,
    ' RightHanded False winds it right-handed about +Y (from +X toward -Z first); the curve itself sits at the far end of
    ' the coordinate-system axis, but the sweep of the sketch along it puts the solid through the sketch (y -1..1).
    Private Function SpiralCoil(ByVal doc As Object, ByVal section As Object, ByVal axisName As String, ByVal cx As Double, ByVal cy As Double, ByVal cz As Double, ByVal pitch As Double, ByVal turns As Double, ByVal rightHand As Boolean) As Object
        Try
341: If axisName <> "Y" Then Throw New Exception("spiral coil: only the Y axis is measured")
342: stepName = "spiral curve"
343: Dim axis As Object = doc.CoordinateSystems.Item(1).Axis(2)
344: Dim r0 As Double = Math.Sqrt(cx * cx + cz * cz)
345: Dim args As Object() = {axis, 1, TypedArray("PointTypeConstants", New Object() {ApiConstant("PointTypeConstants", "igSpacePoint")}), TypedArray("Object", New Object() {Nothing}), New Double() {cx, cy, cz}, BasePlane(doc, "XY"), Not rightHand, ApiConstant("SpiralCurveMethodType", "igSpiralCurveMethodEndDiameterAndTurns"), True, True, 2 * r0, 2 * (r0 + pitch * turns), turns, pitch}
346: Dim method As System.Reflection.MethodInfo = ApiType("HelicalCurves").GetMethod("AddSpiralCurve")
347: Dim curve As Object = method.Invoke(doc.Constructions.HelicalCurves, BindEnums(method, args))
        ' Late-bound HelicalCurve.Edges raises a type mismatch on the installed 2026; the imported signature works.
349: Dim getEdges As System.Reflection.MethodInfo = ApiType("HelicalCurve").GetMethod("get_Edges")
350: Dim edges As Object = getEdges.Invoke(curve, BindEnums(getEdges, New Object() {ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll")}))
351: If CInt(edges.Count) <> 1 Then Throw New Exception("spiral curve failed (" & CStr(edges.Count) & " edges)")
352: stepName = "spiral sweep"
353: Dim model As Object = Sweep3D(doc, edges, section)
        ' The winding: a quarter turn from the start, the wire lies on the rotated side (right hand about +Y: u x ... = -Z for +X).
355: Dim ux As Double = cx / r0, uz As Double = cz / r0
356: Dim vx As Double = If(rightHand, uz, -uz), vz As Double = If(rightHand, -ux, ux)
357: Dim rq As Double = r0 + pitch / 4
358: Dim body As Object = doc.Models.Item(1).Body
359: If Not BodyContains(body, New Double() {rq * vx, cy, rq * vz}) OrElse BodyContains(body, New Double() {-rq * vx, cy, -rq * vz}) Then Throw New Exception("spiral coil wound the wrong way (quarter-turn point not inside the wire)")
360: Return model
        Catch ex As Exception
362: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function BindEnums(ByVal method As System.Reflection.MethodInfo, ByVal values As Object()) As Object()
367: Dim parameters As System.Reflection.ParameterInfo() = method.GetParameters()
368: Dim actual(parameters.Length - 1) As Object
        For i As Integer = 0 To parameters.Length - 1
370: Dim target As Type = parameters(i).ParameterType
371: If target.IsByRef Then target = target.GetElementType()
372: Dim v As Object = If(i < values.Length, values(i), System.Reflection.Missing.Value)
373: If v IsNot Nothing AndAlso v IsNot System.Reflection.Missing.Value AndAlso target.IsEnum Then v = [Enum].ToObject(target, Convert.ToInt32(v))
            actual(i) = v
        Next
376: Return actual
    End Function
    Private Function InvokeModels(ByVal models As Object, ByVal member As String, ByVal args As Object()) As Object
        ' Invoke the imported signature directly so Object parameters retain their VARIANT shape.
380: Dim method As System.Reflection.MethodInfo = ApiType("Models").GetMethod(member)
381: Dim parameters As System.Reflection.ParameterInfo() = method.GetParameters()
382: Dim actual(parameters.Length - 1) As Object
        For i As Integer = 0 To actual.Length - 1
            actual(i) = If(i < args.Length, args(Math.Min(i, args.Length - 1)), System.Reflection.Missing.Value)
        Next
386: Return method.Invoke(models, actual)
    End Function
    Private Function TrySectionShapes(ByVal models As Object, ByVal member As String, ByVal original As Object()) As Object
389: Dim section As Integer = If(member = "AddSweptProtrusion", 4, 1)
390: Dim origin As Integer = section + 2
391: Dim lastFailure As Exception = Nothing
392: Dim signatureLogged As Boolean = False
        LogMessage(member & " shapes: profiles 0=Profile[] 1=Object[]; types 0=Int32[] 1=Object[] of Int32 2=FeaturePropertyConstants[]; origins 0=Object[] of Double[2] 1=Double[n,2] 2=Nothing; maps 0=Nothing 1=empty Object[]")
        For profileKind As Integer = 0 To 1
        For typeKind As Integer = 0 To 2
        For originKind As Integer = 0 To 2
        For mapKind As Integer = 0 To 1
        For traceProfileKind As Integer = 0 To If(section = 4, 1, 0)
        For traceTypeKind As Integer = 0 To If(section = 4, 2, 0)
400: Dim args As Object() = DirectCast(original.Clone(), Object())
            args(section) = ArrayShape(DirectCast(original(section), Array), profileKind, False)
            args(section + 1) = ArrayShape(DirectCast(original(section + 1), Array), typeKind, True)
403: If section = 4 Then
                args(1) = ArrayShape(DirectCast(original(1), Array), traceProfileKind, False)
                args(2) = ArrayShape(DirectCast(original(2), Array), traceTypeKind, True)
            End If
407: If originKind = 1 Then
408: Dim pairs As Array = DirectCast(original(origin), Array)
409: Dim matrix(pairs.Length - 1, 1) As Double
                For i As Integer = 0 To pairs.Length - 1
411: Dim pair As Array = DirectCast(pairs.GetValue(i), Array)
                    matrix(i, 0) = CDbl(pair.GetValue(0))
                    matrix(i, 1) = CDbl(pair.GetValue(1))
                Next
                args(origin) = matrix
            ElseIf originKind = 2 Then
                args(origin) = Nothing
            End If
            args(origin + 1) = If(mapKind = 0, Nothing, New Object() {})
420: Dim shape As String = "profiles=" & profileKind & " types=" & typeKind & " origins=" & originKind & " maps=" & mapKind & " traceProfiles=" & traceProfileKind & " traceTypes=" & traceTypeKind
            Try
422: Dim result As Object = InvokeModels(models, member, args)
423: If result Is Nothing Then Throw New Exception(member & " returned Nothing")
                LogMessage(stepName & " accepted " & shape)
425: Return result
            Catch ex As Exception
427: If Not DispatchError(ex) Then Throw
428: If Not signatureLogged Then
                    LogDispatchFailure(ex, "Models." & member)
                    signatureLogged = True
                End If
                LogMessage(stepName & " rejected " & shape & ": " & SafeError(ex))
                lastFailure = ex
            End Try
        Next
        Next
        Next
        Next
        Next
        Next
441: Throw New Exception(member & " exhausted argument shapes", lastFailure)
    End Function
    Public Sub DiagnoseLoft(ByVal output As String)
444: Dim app As Object = System.Runtime.InteropServices.Marshal.GetActiveObject("SolidEdge.Application")
        Directory.CreateDirectory(output)
        RunFolder = output
447: Dim doc As Object = Nothing
448: Dim alerts As Boolean = CBool(app.DisplayAlerts)
        Try
            app.DisplayAlerts = False
451: doc = app.Documents.Add("SolidEdge.PartDocument")
452: doc.ModelingMode = 2
            InitializeInterop(app)
454: Dim first As Object = BasePlane(doc, "XY")
455: Dim second As Object = doc.RefPlanes.AddParallelByDistance(first, 0.02, ApiConstant("ReferenceElementConstants", "igNormalSide"))
456: Dim profiles As New List(Of Object)()
            For Each plane As Object In New Object() {first, second}
458: Dim profile As Object = doc.ProfileSets.Add().Profiles.Add(plane)
                profile.Circles2d.AddByCenterRadius(0.0, 0.0, 0.005)
460: If CInt(profile.End(1)) <> 0 Then Throw New Exception("Diagnostic circle validation failed")
                profiles.Add(profile)
            Next
463: stepName = "diagnose Models.AddLoftedProtrusion"
464: Dim none As Object = ApiConstant("FeaturePropertyConstants", "igNone")
465: Dim kinds As Array = TypedArray("Int32", New Object() {ApiConstant("FeaturePropertyConstants", "igProfileBasedCrossSection"), ApiConstant("FeaturePropertyConstants", "igProfileBasedCrossSection")})
466: Dim origins As Object() = {New Double() {0, 0}, New Double() {0, 0}}
467: Dim result As Object = TrySectionShapes(doc.Models, "AddLoftedProtrusion", New Object() {2, TypedArray("Profile", profiles.ToArray()), kinds, origins, Nothing, ApiConstant("FeaturePropertyConstants", "igLeft"), none, 0.0, Nothing, none, 0.0, Nothing, none, 0.0, none, 0.0})
            CheckFeature(doc, result, 0, "add", "diagnose Models.AddLoftedProtrusion", True)
            LogMessage("Diagnostic loft succeeded; volume=" & CStr(result.Body.Volume))
        Finally
            Try
472: If doc IsNot Nothing Then doc.Close(False, System.Reflection.Missing.Value, False)
            Finally
                app.DisplayAlerts = alerts
            End Try
        End Try
    End Sub

