    Private Function DiagnosticArguments(ByVal method As System.Reflection.MethodInfo, ByVal edge As Object, ByVal face As Object, ByVal matchPlane As Object, ByVal side As String, ByVal thickness As String) As Object()
526: Dim parameters As System.Reflection.ParameterInfo() = method.GetParameters()
527: Dim args(parameters.Length - 1) As Object
        For i As Integer = 0 To parameters.Length - 1
529: Dim p As System.Reflection.ParameterInfo = parameters(i)
530: Dim key As String = p.Name.ToLowerInvariant()
531: Dim v As Object = System.Reflection.Missing.Value
            Select Case key
                Case "plocatededge", "locatededge", "edge", "pedges", "edgearray" : v = edge
                Case "prefface", "referenceface", "matchface" : v = If(key = "matchface", matchPlane, face)
                Case "flangeside" : v = ApiConstant("FeaturePropertyConstants", side)
                Case "flangelength" : v = 0.02
                Case "thicknessside"
538: If thickness <> "missing" Then v = ApiConstant("FeaturePropertyConstants", thickness)
                Case "insideradius" : v = 0.001
                Case "neutralfactor" : v = 0.44
                Case "bendangle" : v = Math.PI / 2
                Case "flangetype" : v = ApiConstant("FeaturePropertyConstants", If(method.Name = "AddByMatchFace", "igFlangeMatchFace", "igFlangeFullEdge"))
                Case "offsettype", "matchfaceoffsettype" : v = ApiConstant("FeaturePropertyConstants", "igNone")
                Case "offsetvalue", "matchfaceoffsetvalue" : v = 0.0
                Case Else
546: If Not p.IsOptional Then
                        ' Deliberately log unmatched required inputs rather than inventing geometry.
                        LogMessage("UNBOUND required " & p.Name & ":" & p.ParameterType.ToString() & " supplied Nothing")
                        v = Nothing
                    End If
            End Select
            args(i) = v
553: Dim rendered As String = If(v Is System.Reflection.Missing.Value, "Missing", If(v Is Nothing, "Nothing", If(System.Runtime.InteropServices.Marshal.IsComObject(v), "COM geometry", Convert.ToString(v, Globalization.CultureInfo.InvariantCulture))))
            LogMessage("  " & p.Name & "=" & rendered)
        Next
556: Return BindFlangeArguments(method, args)
    End Function
    Private Function BindFlangeArguments(ByVal method As System.Reflection.MethodInfo, ByVal values As Object()) As Object()
559: Dim parameters As System.Reflection.ParameterInfo() = method.GetParameters()
560: If values.Length <> parameters.Length Then Throw New Exception("Flange argument count differs from installed signature")
561: Dim args(parameters.Length - 1) As Object
        For i As Integer = 0 To parameters.Length - 1
563: Dim p As System.Reflection.ParameterInfo = parameters(i)
564: Dim v As Object = values(i)
565: Dim target As Type = p.ParameterType
566: If target.IsByRef Then target = target.GetElementType()
567: If v IsNot Nothing AndAlso v IsNot System.Reflection.Missing.Value AndAlso target.IsEnum Then v = [Enum].ToObject(target, Convert.ToInt32(v))
            args(i) = v
        Next
570: Return args
    End Function
    Private Function InvokeMultiEdgeFlange(ByVal flanges As Object, ByVal values As Object()) As Object
573: Dim method As System.Reflection.MethodInfo = ApiType("MultiEdgeFlanges").GetMethod("Add")
574: If method Is Nothing Then Throw New Exception("Installed MultiEdgeFlanges.Add signature missing")
575: Return method.Invoke(flanges, BindFlangeArguments(method, values))
