    Private Function EdgeStartsLow(ByVal edge As Object) As Boolean
578: Dim start(2), finish(2) As Double
        edge.StartVertex.GetPointData(start)
        edge.EndVertex.GetPointData(finish)
581: Dim axis As Integer = 0
        For k As Integer = 1 To 2
583: If Math.Abs(finish(k) - start(k)) > Math.Abs(finish(axis) - start(axis)) Then axis = k
        Next
585: Return start(axis) < finish(axis)
    End Function
    ' Real run on our Solid Edge test PC (2026-11-22): the from-end flange extents count from the edge's own start vertex (type 138) or end
    ' vertex (139); the two-offset type (140) takes the start-vertex offset first. The recipes count from the low end.
    Private Function FlangeExtent(ByVal edge As Object, ByVal kind As String) As Integer
590: If kind = "offset" Then Return CInt(ApiConstant("FeaturePropertyConstants", "igFlangeFromBothEndsOfEdge"))
591: Return CInt(ApiConstant("FeaturePropertyConstants", If(EdgeStartsLow(edge), "igFlangeStartFromEndEdge", "igFlangeEndFromEndEdge")))
    End Function
    Private Function FlangeWidth1(ByVal edge As Object, ByVal kind As String, ByVal first As Double, ByVal second As Double) As Double
594: If kind = "offset" AndAlso Not EdgeStartsLow(edge) Then Return second
595: Return first
    End Function
    Private Function FlangeWidth2(ByVal edge As Object, ByVal kind As String, ByVal first As Double, ByVal second As Double) As Double
598: If kind = "offset" AndAlso Not EdgeStartsLow(edge) Then Return first
599: Return second
    End Function
    Private Function InvokeFlange(ByVal flanges As Object, ByVal values As Object()) As Object
602: Dim method As System.Reflection.MethodInfo = ApiType("Flanges").GetMethod("Add")
603: Return method.Invoke(flanges, BindFlangeArguments(method, values))
    End Function
    Public Sub DiagnoseFlange(ByVal output As String)
        Directory.CreateDirectory(output)
        RunFolder = output
608: Dim app As Object = System.Runtime.InteropServices.Marshal.GetActiveObject("SolidEdge.Application")
        InitializeInterop(app)
610: Dim alerts As Boolean = CBool(app.DisplayAlerts)
611: Dim methods As New List(Of System.Reflection.MethodInfo)()
        Try
            app.DisplayAlerts = False
            LogMessage("BEGIN flange diagnostic; volumes m^3; endpoints and ranges m; fresh document per attempt")
            ' Inventory first, including all creation members on Flanges and any flange member on Models.
            For Each owner As String In New String() {"Flanges", "Models", "EdgebarFeatures"}
                Try
618: Dim found As Integer = 0
                    For Each method As System.Reflection.MethodInfo In ApiType(owner).GetMethods()
620: If method.Name.IndexOf("Flange", StringComparison.OrdinalIgnoreCase) < 0 AndAlso Not (owner = "Flanges" AndAlso method.Name.StartsWith("Add")) Then Continue For
                        found += 1
622: Dim parameters As New List(Of String)()
                        For Each p As System.Reflection.ParameterInfo In method.GetParameters()
                            parameters.Add(p.Name & ":" & p.ParameterType.ToString() & If(p.IsOptional, " optional", " required"))
                        Next
                        LogMessage("INSTALLED " & owner & "." & method.Name & "(" & String.Join(", ", parameters.ToArray()) & ") -> " & method.ReturnType.ToString())
627: If method.Name.StartsWith("Add") Then methods.Add(method)
                    Next
                    LogMessage(owner & " matching methods=" & CStr(found))
                Catch ex As Exception
                    LogMessage(owner & " inventory unavailable: " & SafeError(ex))
                End Try
            Next
            ' Eight straight perimeter edges: four at z=.002 and four at z=0.
635: Dim corners As Double(,) = {{0, 0}, {0.1, 0}, {0.1, 0.06}, {0, 0.06}}
636: Dim attempt As Integer = 0
            For Each method As System.Reflection.MethodInfo In methods
            For Each z As Double In New Double() {0.002, 0.0}
            For edgeIndex As Integer = 0 To 3
            For Each side As String In New String() {"igLeft", "igRight"}
            For Each thickness As String In New String() {"igLeft", "igRight", "missing"}
            For Each recompute As Boolean In New Boolean() {False, True}
                attempt += 1
644: Dim doc As Object = Nothing, model As Object = Nothing, flange As Object = Nothing
645: Dim label As String = "case=" & CStr(attempt) & " " & method.DeclaringType.Name & "." & method.Name & " edge=" & CStr(edgeIndex) & " z=" & CStr(z) & " side=" & side & " thickness=" & thickness & " recompute=" & CStr(recompute)
                LogMessage(label)
                Try
                    model = DiagnosticBaseTab(app, doc)
                    DiagnosticReadings(doc, model, Nothing, "before")
650: Dim j As Integer = (edgeIndex + 1) Mod 4
651: Dim x As Double = (corners(edgeIndex, 0) + corners(j, 0)) / 2
652: Dim y As Double = (corners(edgeIndex, 1) + corners(j, 1)) / 2
653: Dim edge As Object = EdgeAt(model, x, y, z, If(edgeIndex Mod 2 = 0, 0, 1))
654: Dim a(2), b(2) As Double
                    edge.StartVertex.GetPointData(a)
                    edge.EndVertex.GetPointData(b)
                    LogMessage("selected endpoints(m)=" & String.Join(",", Array.ConvertAll(a, Function(v) CStr(v))) & " -> " & String.Join(",", Array.ConvertAll(b, Function(v) CStr(v))))
658: Dim face As Object = FaceAt(model, x, y, z, 0, 0, If(z > 0, 1, -1))
659: Dim matchPlane As Object = Nothing
660: If method.Name = "AddByMatchFace" Then
661: Dim axis As Integer = If(edgeIndex Mod 2 = 0, 1, 0)
662: Dim base As Object = BasePlane(doc, If(axis = 1, "XZ", "YZ"))
663: Dim location As Double = If(axis = 1, y, x)
664: Dim sign As Integer = If(edgeIndex = 0 OrElse edgeIndex = 3, -1, 1)
665: Dim offset As Double = location + sign * 0.02
                        matchPlane = doc.RefPlanes.AddParallelByDistance(base, Math.Abs(offset), PlaneSide(base, axis, If(offset >= 0, 2, 1)))
                        LogMessage("MatchFace reference plane offset(m)=" & CStr(offset))
                    End If
669: Dim owner As Object = Nothing
                    Select Case method.DeclaringType.Name
                        Case "Flanges" : owner = model.Flanges
                        Case "Models" : owner = doc.Models
                        Case "EdgebarFeatures"
                            Try
                                owner = model.EdgebarFeatures
                            Catch ex As Exception
                                owner = doc.EdgebarFeatures
                            End Try
                        Case Else : Throw New Exception("Unsupported declaring interface " & method.DeclaringType.Name)
                    End Select
681: Dim args As Object() = DiagnosticArguments(method, edge, face, matchPlane, side, thickness)
                    Try
                        flange = method.Invoke(owner, args)
                        LogMessage("creation returned " & If(flange Is Nothing, "Nothing", "object"))
                    Catch ex As Exception
                        LogMessage("creation failed: " & SafeError(ex))
                    End Try
688: If recompute Then
                        Try
                            doc.Recompute()
                            LogMessage("Recompute completed")
                        Catch ex As Exception
                            LogMessage("Recompute unavailable: " & SafeError(ex))
                        End Try
                    End If
                    DiagnosticReadings(doc, model, flange, "after")
                Catch ex As Exception
                    LogMessage(label & " failed: " & SafeError(ex))
                Finally
700: If doc IsNot Nothing Then
                        Try
702: doc.Close(False, System.Reflection.Missing.Value, False)
                        Catch ex As Exception
                            LogMessage("close failed: " & SafeError(ex))
                        End Try
                    End If
                End Try
            Next
            Next
            Next
            Next
            Next
            Next
            LogMessage("END flange diagnostic; attempts=" & CStr(attempt))
        Finally
            app.DisplayAlerts = alerts
        End Try
    End Sub

    Private Sub ValidateLoftSections(ByVal profiles As Array, ByVal planes As Array)
        For i As Integer = 0 To planes.Length - 1
722: Dim normal(2), root(2) As Double
723: Dim plane As Object = planes.GetValue(i)
724: plane.GetNormal(normal)
725: plane.GetRootPoint(root)
            LogMessage("Loft section " & CStr(i) & " root(m)=" & String.Join(",", Array.ConvertAll(root, Function(v) CStr(v))) & " normal=" & String.Join(",", Array.ConvertAll(normal, Function(v) CStr(v))))
            For j As Integer = 0 To i - 1
728: Dim otherNormal(2), otherRoot(2) As Double
729: Dim other As Object = planes.GetValue(j)
                other.GetNormal(otherNormal)
                other.GetRootPoint(otherRoot)
732: Dim dot As Double = 0, distance As Double = 0
                For k As Integer = 0 To 2
                    dot += normal(k) * otherNormal(k)
                    distance += normal(k) * (root(k) - otherRoot(k))
                Next
737: If Math.Abs(dot) > 0.999999 AndAlso Math.Abs(distance) < 0.0000001 Then Throw New Exception("Coincident loft section planes")
            Next
        Next
    End Sub

    Private Function BodyVolume(ByVal doc As Object) As Double
743: Dim total As Double = 0
        For i As Integer = 1 To doc.Models.Count
745: Dim volume As Double
            Try
                volume = CDbl(doc.Models.Item(i).Body.Volume)
            Catch readFailure As System.Runtime.InteropServices.COMException
                ' Measured on our Solid Edge test PC: after an intersect the consumed tool body stays in the model list but has no readable body.
                Continue For
            End Try
752: If Double.IsNaN(volume) OrElse Double.IsInfinity(volume) OrElse volume <= 0 Then Throw New Exception("Invalid body volume")
            total += volume
        Next
755: Return total
    End Function
    Private Sub CheckFeature(ByVal doc As Object, ByVal feature As Object, ByVal before As Double, ByVal effect As String, ByVal label As String, ByVal isModel As Boolean)
        ' Real Solid Edge 2026: reading Status (or a Model's Features) on a good feature can raise E_FAIL, and
        ' Status codes vary by feature type. The volume change is the dependable signal: a feature that leaves
        ' the body unchanged (or an additive one that does not add) is a silent failure.
761: If feature Is Nothing Then Throw New Exception(label & ": returned no feature")
762: Dim after As Double = BodyVolume(doc)
763: Dim tolerance As Double = Math.Max(0.000000000000001, Math.Abs(before) * 0.000000001)
764: If Math.Abs(after - before) <= tolerance OrElse (effect = "add" AndAlso after <= before + tolerance) Then Throw New Exception(label & ": feature changed nothing or did not add material; volume before=" & CStr(before) & " after=" & CStr(after) & " m^3")
765: If label = "model.MultiEdgeFlanges.Add" OrElse label = "model.Flanges.Add" Then
766: Dim low(2), high(2) As Double
            doc.Models.Item(1).Body.GetRange(low, high)
768: If (flangeDirection = "+Z" AndAlso high(2) <= flangeBeforeHigh(2) + 0.0000001) OrElse (flangeDirection = "-Z" AndAlso low(2) >= flangeBeforeLow(2) - 0.0000001) Then Throw New Exception(label & ": flange did not grow in requested direction " & flangeDirection)
        End If
    End Sub
    Private flangeBeforeLow(2), flangeBeforeHigh(2) As Double
    Private flangeDirection As String
    Private Function FlangeDiagnostic(ByVal model As Object, ByVal direction As String, ByVal edge As Object, ByVal side As Object, ByVal height As Double, ByVal radius As Double, ByVal neutral As Double, ByVal angle As Double) As Object
774: Dim start(2), finish(2) As Double
        flangeDirection = direction
        model.Body.GetRange(flangeBeforeLow, flangeBeforeHigh)
        edge.StartVertex.GetPointData(start)
        edge.EndVertex.GetPointData(finish)
        flangeDiagnosticText = "MultiEdgeFlanges.Add endpoints(m)=(" & String.Join(",", Array.ConvertAll(Of Double, String)(start, Function(v As Double) v.ToString("R", Globalization.CultureInfo.InvariantCulture))) & ") -> (" & String.Join(",", Array.ConvertAll(Of Double, String)(finish, Function(v As Double) v.ToString("R", Globalization.CultureInfo.InvariantCulture))) & "); side=" & CStr(side) & ", length(m)=" & CStr(height) & ", radius and neutral factor taken from the document rules (" & CStr(radius) & ", " & CStr(neutral) & "), angle(rad)=" & CStr(angle) & ", one edge"
780: Dim method As System.Reflection.MethodInfo = ApiType("MultiEdgeFlanges").GetMethod("Add")
781: If method Is Nothing Then Throw New Exception("Installed MultiEdgeFlanges.Add signature missing")
782: If method.GetParameters().Length <> 26 Then Throw New Exception("Installed MultiEdgeFlanges.Add has " & CStr(method.GetParameters().Length) & " parameters; expected 26")
783: If height <= 0 Then Throw New Exception("FlangeLength must be positive meters")
784: Return Nothing
    End Function
    Private Function PlaneSide(ByVal plane As Object, ByVal axis As Integer, ByVal side As Integer) As Integer
        Try
788: If side = 3 Then Return side
789: Dim normal(2) As Double
790: plane.GetNormal(normal)
791: If Math.Abs(normal(axis)) < 0.999999 Then Throw New Exception("Extrusion/offset axis is not normal to sketch plane")
792: Return If(normal(axis) < 0, 3-side, side)
        Catch ex As Exception
794: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function Coordinate(ByVal profile As Object, ByVal x As Double, ByVal y As Double, ByVal z As Double, ByVal index As Integer) As Double
        Try
800: Dim u, v As Double
801: profile.Convert3DCoordinate(x, y, z, u, v)
802: Return If(index = 0, u, v)
        Catch ex As Exception
804: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function BasePlane(ByVal doc As Object, ByVal name As String) As Object
        Try
        ' Identify defaults by measured normals, independent of template plane order.
811: Dim axis As Integer = If(name = "XY", 2, If(name = "XZ", 1, 0))
812: Dim matches As New List(Of Object)()
        For i As Integer = 1 To doc.RefPlanes.Count
814: Dim candidate As Object = doc.RefPlanes.Item(i)
815: Dim normal(2), root(2) As Double
816: candidate.GetNormal(normal)
817: candidate.GetRootPoint(root)
818: If Math.Abs(normal(axis)) > 0.999999 AndAlso Math.Abs(root(axis)) < 0.0000001 Then matches.Add(candidate)
        Next
820: If matches.Count <> 1 Then Throw New Exception("Expected one origin reference plane " & name & "; found " & matches.Count)
821: Return matches(0)
        Catch ex As Exception
823: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function Unique(ByVal matches As List(Of Object), ByVal label As String) As Object
        Try
829: If matches.Count <> 1 Then Throw New Exception(label & " selector expected one match; found " & matches.Count)
830: Return matches(0)
        Catch ex As Exception
832: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function FaceAt(ByVal model As Object, ByVal x As Double, ByVal y As Double, ByVal z As Double, ByVal nx As Double, ByVal ny As Double, ByVal nz As Double) As Object
        Try
838: Dim matches As New List(Of Object)()
839: Dim faces As Object = model.Body.Faces(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
        For i As Integer = 1 To faces.Count
841: Dim face As Object = faces.Item(i)
842: Dim low(2), high(2) As Double
843: Dim points() As Double = {x, y, z}
844: face.GetRange(low, high)
845: Dim inside As Boolean = True
            For k As Integer = 0 To 2
847: If points(k) < low(k) - 0.0000001 OrElse points(k) > high(k) + 0.0000001 Then inside = False
            Next
849: If inside Then
850: Dim guess(1), deviations(0), parameters(1), normal(2), evaluated(2) As Double
                deviations(0) = 0.0000001
852: Dim flags(0) As Integer
853: Dim onFace(0) As Boolean
854: face.GetParamAtPoint(1, points, guess, deviations, parameters, flags)
855: face.GetNormal(1, parameters, normal)
856: face.GetPointAtParam(1, parameters, evaluated)
857: face.GetParamOnFace(1, parameters, onFace)
858: Dim distance As Double = Math.Sqrt((evaluated(0)-x)^2 + (evaluated(1)-y)^2 + (evaluated(2)-z)^2)
859: If onFace(0) AndAlso flags(0) = 0 AndAlso distance < 0.0000001 AndAlso normal(0) * nx + normal(1) * ny + normal(2) * nz > 0.999999 Then matches.Add(face)
            End If
        Next
862: Return Unique(matches, "face")
        Catch ex As Exception
864: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function EdgeAt(ByVal model As Object, ByVal x As Double, ByVal y As Double, ByVal z As Double, ByVal axis As Integer) As Object
        Try
870: Dim matches As New List(Of Object)()
871: Dim edges As Object = model.Body.Edges(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
        For i As Integer = 1 To edges.Count
873: Dim edge As Object = edges.Item(i)
874: Dim low(2), high(2) As Double
875: Dim point() As Double = {x, y, z}
876: edge.GetRange(low, high)
877: Dim fits As Boolean = high(axis) - low(axis) > 0.0000001
            For k As Integer = 0 To 2
879: If point(k) < low(k) - 0.0000001 OrElse point(k) > high(k) + 0.0000001 Then fits = False
880: If k <> axis AndAlso high(k) - low(k) > 0.0000001 Then fits = False
            Next
882: If fits Then matches.Add(edge)
        Next
884: Return Unique(matches, "straight edge")
        Catch ex As Exception
886: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function VertexAt(ByVal edge As Object, ByVal x As Double, ByVal y As Double, ByVal z As Double) As Object
        Try
892: Dim matches As New List(Of Object)()
        For Each vertex As Object In New Object() {edge.StartVertex, edge.EndVertex}
894: Dim p(2) As Double
895: vertex.GetPointData(p)
896: If Math.Abs(p(0)-x) + Math.Abs(p(1)-y) + Math.Abs(p(2)-z) < 0.0000001 Then matches.Add(vertex)
        Next
898: Return Unique(matches, "vertex")
        Catch ex As Exception
900: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function AdjacentFaces(ByVal model As Object, ByVal edge As Object) As List(Of Object)
905: Dim matches As New List(Of Object)()
906: Dim faces As Object = model.Body.Faces(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
        For i As Integer = 1 To faces.Count
908: Dim face As Object = faces.Item(i)
909: Dim edges As Object = face.Edges
            For j As Integer = 1 To edges.Count
911: If CStr(edges.Item(j).ID) = CStr(edge.ID) Then
                    matches.Add(face)
                    Exit For
                End If
            Next
        Next
917: Return matches
    End Function

    Private Function ChamferFace(ByVal model As Object, ByVal edge As Object, ByVal flip As Boolean) As Object
        Try
        ' Canonical order by world-space bounds, rather than transient face indices.
923: Dim faces As List(Of Object) = AdjacentFaces(model, edge)
924: If faces.Count <> 2 Then Throw New Exception("Chamfer edge must have two adjacent faces")
925: Dim a As Object = faces.Item(0), b As Object = faces.Item(1)
926: Dim sa As String = FaceKey(a), sb As String = FaceKey(b)
927: If sa = sb Then Throw New Exception("Cannot order adjacent chamfer faces")
928: Return If((String.CompareOrdinal(sa, sb) < 0) Xor flip, a, b)
        Catch ex As Exception
930: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function FaceKey(ByVal face As Object) As String
        Try
936: Dim low(2), high(2) As Double
937: face.GetRange(low, high)
938: Return String.Join(",", Array.ConvertAll(low, Function(v) v.ToString("R", Globalization.CultureInfo.InvariantCulture))) & ";" & String.Join(",", Array.ConvertAll(high, Function(v) v.ToString("R", Globalization.CultureInfo.InvariantCulture)))
        Catch ex As Exception
940: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function
    Private Function OtherFace(ByVal model As Object, ByVal edge As Object, ByVal face As Object) As Object
        Try
946: Dim faces As List(Of Object) = AdjacentFaces(model, edge)
947: If faces.Count <> 2 Then Throw New Exception("Chamfer edge must have two adjacent faces")
948: If CStr(faces.Item(0).ID) <> CStr(face.ID) AndAlso CStr(faces.Item(1).ID) <> CStr(face.ID) Then Throw New Exception("Reference face is not adjacent to chamfer edge")
        For i As Integer = 0 To 1
950: If CStr(faces.Item(i).ID) <> CStr(face.ID) Then Return faces.Item(i)
        Next
952: Throw New Exception("No opposite chamfer face")
        Catch ex As Exception
954: If Not ex.Data.Contains("FixtureLine") Then ex.Data("FixtureLine") = Erl()
            Throw
        End Try
    End Function

    Private jointRecords As New List(Of Object)()
    Private Sub CheckJoint(ByVal relation As Object, ByVal kind As String, ByVal offset As Double, ByVal angle As Double, ByVal aligned As Boolean)
961: Dim status As Integer=CInt(relation.Status), detailed As Integer=CInt(relation.DetailedStatus)
962: Dim record As New Dictionary(Of String,Object) From {{"kind",kind},{"status",status},{"detailed_status",detailed}}
        jointRecords.Add(record)
964: Dim misses As New List(Of String)()
        CompareNumber(misses,"joint status",status,ApiConstant("Relation3dStatusConstants","igRelation3dStatusSolved"),0)
        CompareNumber(misses,"joint detailed status",detailed,ApiConstant("Relation3dDetailedStatusConstants","igRelation3dDetailedStatusSolved"),0)
967: Dim topology1 As Boolean=False,topology2 As Boolean=False
968: Dim element1 As Object=relation.GetElement1(topology1),element2 As Object=relation.GetElement2(topology2)
        record("references")=New Boolean(){element1 IsNot Nothing,element2 IsNot Nothing}
970: If element1 Is Nothing OrElse element2 Is Nothing OrElse relation.Occurrence1 Is Nothing OrElse relation.Occurrence2 Is Nothing Then misses.Add("joint must retain two occurrence geometry references")
971: If kind="planar" Then
            record("offset_mm")=CDbl(relation.Offset)*1000
            record("normals_aligned")=CBool(relation.NormalsAligned)
            CompareNumber(misses,"joint offset mm",record("offset_mm"),offset*1000,LengthTolerance)
975: If CBool(record("normals_aligned"))<>aligned Then misses.Add("joint normal alignment: measured " & CStr(record("normals_aligned")) & ", expected " & CStr(aligned))
        ElseIf kind="ranged" Then
            ' offset = range low, angle = range high (meters), aligned = normals aligned; re-read after the poses.
            record("range_mm")=New Double(){CDbl(relation.RangeLow)*1000,CDbl(relation.RangeHigh)*1000}
979: If Not CBool(relation.RangedOffset) Then misses.Add("joint travel range is no longer set")
            CompareNumber(misses,"joint range low mm",CDbl(relation.RangeLow)*1000,offset*1000,LengthTolerance)
            CompareNumber(misses,"joint range high mm",CDbl(relation.RangeHigh)*1000,angle*1000,LengthTolerance)
982: If CBool(relation.NormalsAligned)<>aligned Then misses.Add("joint normal alignment: measured " & CStr(relation.NormalsAligned) & ", expected " & CStr(aligned))
        ElseIf kind="axialz" Then
            ' aligned = the turn about the axis is free
            record("fixed_rotate")=CBool(relation.FixedRotate)
986: If CBool(relation.FixedRotate)=aligned Then misses.Add("axial FixedRotate is " & CStr(relation.FixedRotate) & ", expected " & CStr(Not aligned))
        ElseIf kind="angular" Then
            record("angle_deg")=CDbl(relation.Angle)*180/Math.PI
            CompareNumber(misses,"joint angle deg",record("angle_deg"),angle*180/Math.PI,0.01)
        End If
991: If misses.Count>0 Then
992: Dim ex As New Exception(String.Join("; ",misses.ToArray()))
            ex.Data("ExpectationMismatch")=True
            Throw ex
        End If
    End Sub
    ' Fusion joints of the F10 recipes: a pin (bottom center at its origin) on the top-face center of a block (z 0..10), axis Z.
    ' Measured on our Solid Edge test PC (2026-11-23, Solid Edge 2026): the block's own base coordinate system gives the axis the block has no
    ' feature for (CoordinateSystems.Item(1).Axis(3) is an edge AddAxial accepts), so the parts stay as the recipe makes them.
    '   rigid    = planar mate pin bottom / block top (offset) + pin YZ flush block YZ + pin XZ flush block XZ
    '   revolute = axial pin Z axis / block Z axis with FixedRotate False (it defaults to True, which locks the turn) + the mate
    '   slider   = the two flush plane pairs (Z stays free)
    ' Occurrence.Move and Rotate raise E_FAIL on every occurrence, so the freedom is proved with PutTransform: a locked
    ' coordinate snaps back to the solved pose, a free one keeps the new value.
    Private Function ComponentFile(ByVal doc As Object, ByVal partId As String) As String
1006: Dim keep As String = currentRecipe
        Try
            DBuildPart(doc.Application, partId)
        Finally
            currentRecipe = keep
        End Try
1012: Return Dependency(partId)
    End Function
    Private Function OccurrenceFaceZ(ByVal occurrence As Object, ByVal z As Double, ByVal halfWidth As Double) As Object
1015: Dim faces As Object = occurrence.OccurrenceDocument.Models.Item(1).Body.Faces(ApiConstant("FeatureTopologyQueryTypeConstants", "igQueryAll"))
1016: Dim found As New List(Of Object)()
        For i As Integer = 1 To CInt(faces.Count)
1018: Dim f As Object = faces.Item(i)
1019: Dim lo(2), hi(2) As Double
            f.GetRange(lo, hi)
1021: If Math.Abs(hi(2) - lo(2)) < 0.0000001 AndAlso Math.Abs(lo(2) - z) < 0.000001 AndAlso (halfWidth = 0 OrElse Math.Abs(hi(0) - halfWidth) < 0.000001) Then found.Add(f)
        Next
1023: Return Unique(found, "planar face at z " & CStr(z * 1000) & " mm")
    End Function
    Private Function JointPlanar(ByVal doc As Object, ByVal a As Object, ByVal b As Object, ByVal aligned As Boolean, ByVal offset As Double, ByVal pa As Double(), ByVal pb As Double()) As Object
1026: Dim relation As Object = doc.Relations3d.AddPlanar(a, b, aligned, pa, pb)
        relation.FixedOffset = True
        relation.Offset = offset
        relation.NormalsAligned = aligned
1030: Return relation
    End Function
    Private Function PoseOf(ByVal occurrence As Object) As Double()
1033: Dim x, y, z, ax, ay, az As Double
        occurrence.GetTransform(x, y, z, ax, ay, az)
1035: Return New Double() {x, y, z, ax, ay, az}
    End Function
    Private Sub FusionJoint(ByVal doc As Object, ByVal block As Object, ByVal pin As Object, ByVal kind As String, ByVal offset As Double)
1038: stepName = "joint " & kind
1039: Dim z0 As Double = 0.01 + offset
        ' Start the pin away from the joint so the solver has to pull it in (a slider keeps its height, so it starts at the joint height).
        pin.PutTransform(0.03, 0.02, If(kind = "slider", z0, 0.05), 0, 0, 0)
1042: Dim top As Object = doc.CreateReference(block, OccurrenceFaceZ(block, 0.01, 0))
1043: Dim bottom As Object = doc.CreateReference(pin, OccurrenceFaceZ(pin, 0, 0.0025))
1044: Dim mid As Double() = {0, 0, 0.005}
1045: If kind = "revolute" Then
1046: Dim axial As Object = doc.Relations3d.AddAxial(doc.CreateReference(pin, pin.OccurrenceDocument.CoordinateSystems.Item(1).Axis(3)), doc.CreateReference(block, block.OccurrenceDocument.CoordinateSystems.Item(1).Axis(3)), True)
            axial.FixedRotate = False
            CheckJoint(axial, "axial", 0, 0, False)
        Else
            For Each name As String In New String() {"YZ", "XZ"}
                CheckJoint(JointPlanar(doc, doc.CreateReference(pin, BasePlane(pin.OccurrenceDocument, name)), doc.CreateReference(block, BasePlane(block.OccurrenceDocument, name)), True, 0, mid, mid), "planar", 0, 0, True)
