1990: Dim outside As Double=width*thickness*((legA-radius)+(legB-radius)+bend)
1991: Dim low(2),high(2) As Double:model.Body.GetExactRange(low,high)
1992: Dim insideBox As Boolean=Math.Abs(low(2))<0.0000001 AndAlso Math.Abs(high(0)-legA)<0.0000001
1993: Dim outsideBox As Boolean=Math.Abs(low(2)+thickness)<0.0000001 AndAlso Math.Abs(high(0)-legA-thickness)<0.0000001
