'@
    $crash = $null
    try { [SolidEdgeFixtureBuilder]::Run($buildParent, $designs) } catch { $crash = $_ }
    $run = [SolidEdgeFixtureBuilder]::RunFolder
    # The sweep runs after a crash too: nobody zipping the folder by hand gets private files.
    if ($run -and [IO.Directory]::Exists($run)) { Invoke-PrivacySweep $run; Update-PrivacyResults $run }
    if ($crash) { throw $crash }
    Add-Type -AssemblyName System.IO.Compression
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    # ZipFile.CreateFromDirectory under Windows PowerShell 5.1 writes backslash entry names (measured on our Solid Edge test PC, .NET 4.8:
    # 'build_solidedge-...\A01a.asm'), which the zip format forbids and unzip/Python read as one flat name. Entries are written
    # one by one with forward slashes, under the run folder's name; files the privacy sweep removed are left out.
    $top = Split-Path -Leaf $run
    $za = [IO.Compression.ZipFile]::Open(($run + '.zip'), [IO.Compression.ZipArchiveMode]::Create)
    try {
        foreach ($f in @(Get-ChildItem -LiteralPath $run -Recurse -File -Force)) {
            if ($script:PrivacyDropped.ContainsKey($f.FullName)) { continue }
            $rel = $f.FullName.Substring($run.TrimEnd('\').Length + 1).Replace('\', '/')
            [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($za, $f.FullName, ($top + '/' + $rel), [IO.Compression.CompressionLevel]::Optimal)
        }
    } finally { $za.Dispose() }
    $zip = $run + '.zip'
    if ($buildParent -ne $chosen) {
        # Never overwrite: the copy takes the first free name in the chosen folder.
        [void][IO.Directory]::CreateDirectory($chosen)
        $copy = Join-Path $chosen ($top + '.zip'); $n = 2
        while ([IO.File]::Exists($copy)) { $copy = Join-Path $chosen ($top + '-' + $n + '.zip'); $n++ }
        [IO.File]::Copy($zip, $copy)
        Write-Output ('Built in ' + $run + ', a neutral folder, so no folder of yours is recorded in the files.')
        $zip = $copy
    }
    $rows = @()
    # Windows PowerShell 5.1 hands a JSON array on as ONE object; the second pipeline unrolls it, so the counts below are per recipe.
    try { $rows = @((Get-Content -Raw -Path (Join-Path $run 'results.json') | ConvertFrom-Json) | ForEach-Object { $_ }) } catch { }
    $built = @($rows | Where-Object { $_.status -eq 'ok' }).Count
    $notScripted = @($rows | Where-Object { $_.status -eq 'not_scripted' }).Count
    $failed = $rows.Count - $built - $notScripted
    $plural = if ($rows.Count -eq 1) { '' } else { 's' }
    foreach ($note in $script:PrivacyNotes) { Write-Output $note }
    Write-Output ('Output folder: ' + (Hide-PrivatePath $run))
    Write-Output ([string]$rows.Count + ' recipe' + $plural + ': ' + $built + ' built, ' + $failed + ' failed, ' + $notScripted + ' not scripted (details in FixtureBuilder.log).')
    Write-Output 'Next: send this zip to Dutchy in a Discord direct message:'
    Write-Output (Hide-PrivatePath $zip)
    # A person at a console gets the zip selected in Explorer; FIXTURE_UNATTENDED=1, a redirected or a scheduled run never opens a window.
    # This script attaches to the Solid Edge you started; it never starts, shows or hides it.
    if ($env:FIXTURE_UNATTENDED -ne '1' -and [Environment]::UserInteractive -and -not [Console]::IsOutputRedirected -and -not [Console]::IsInputRedirected) {
        try { Start-Process -FilePath 'explorer.exe' -ArgumentList ('/select,"' + $zip + '"') } catch { }
    }
} catch {
    # Volunteers screenshot the console: the error is shown with user folders and names hidden.
    foreach ($note in $script:PrivacyNotes) { Write-Output $note }
    Write-Output ('The builder stopped: ' + (Hide-PrivatePath ($_ | Out-String)))
    exit 1
}
